#include "test.h"
#include "../src/game/city.h"
#include "../src/game/skyline.h"

/*
 * The table of what's seen from each roof (city_seen, generated by tools/make_city_seen.py) is
 * worked out again here with the game's own hiding code (game/skyline.h), and must match it bit
 * for bit. So a change to city.c's towers without running the tool again fails here, and so does
 * the tool's rule drifting from the game's.
 * Positions as city.h has them: out along the corridor, across it
 */

static skyline_box box_of(const city_tower *t)
{
	skyline_box b = {t->out_min, t->out_max, t->across_min, t->across_max, t->height};

	return b;
}

// The hiders: every tower, then every block of 2 x 2 (the last column's are 1 x 2), as low as
// its lowest
#define HIDERS (CITY_TOWERS + ((CITY_COLUMNS + 1) / 2) * (CITY_ROWS / 2))
static skyline_box hiders[HIDERS];

static void set_hiders(void)
{
	int n = 0;

	for (int i = 0; i < CITY_TOWERS; ++i)
		hiders[n++] = box_of(&city_towers[i]);
	for (int br = 0; br < CITY_ROWS; br += 2)
		for (int bc = 0; bc < CITY_COLUMNS; bc += 2)
		{
			skyline_box block = box_of(city_tower_at(bc, br));

			for (int r = br; r < br + 2; ++r)
				for (int c = bc; c < bc + 2 && c < CITY_COLUMNS; ++c)
				{
					const skyline_box t = box_of(city_tower_at(c, r));

					if (t.x_min < block.x_min)
						block.x_min = t.x_min;
					if (t.x_max > block.x_max)
						block.x_max = t.x_max;
					if (t.y_min < block.y_min)
						block.y_min = t.y_min;
					if (t.y_max > block.y_max)
						block.y_max = t.y_max;
					if (t.top < block.top)
						block.top = t.top;
				}
			hiders[n++] = block;
		}
}

// Whether hider a hides box b from the eye at (x, y), z up: the game's rule, one hider offered
static bool hides_from(int x, int y, int z, const skyline_box *a, const skyline_box *b)
{
	skyline s;

	// Looking straight at the hider's middle: skyline_offer only keeps what's in front
	skyline_begin(&s, x, y, z, a->x_min + a->x_max - 2 * x, a->y_min + a->y_max - 2 * y);
	skyline_offer(&s, a);
	return s.count == 1 && skyline_hides_level(&s, b);
}

static bool seen(int from, int patch, int tower)
{
	const city_tower *roof = &city_towers[from];
	const skyline_box target = box_of(&city_towers[tower]);
	const int step = CITY_TOWER_SIZE / CITY_SEEN_PATCHES;
	const int x0 = roof->out_min + (patch % CITY_SEEN_PATCHES) * step;
	const int y0 = roof->across_min + (patch / CITY_SEEN_PATCHES) * step;
	const int z = roof->height + CITY_SEEN_EYE;

	if (tower == from)
		return true;
	for (int h = 0; h < HIDERS; ++h)
	{
		const skyline_box *a = &hiders[h];

		if (h == tower || a->top < target.top || a->top < z)
			continue;
		// The same hider from all four corners of the patch: then from everywhere in it
		if (hides_from(x0, y0, z, a, &target) && hides_from(x0 + step, y0, z, a, &target) &&
			hides_from(x0 + step, y0 + step, z, a, &target) && hides_from(x0, y0 + step, z, a, &target))
			return false;
	}
	return true;
}

static void the_table_is_what_the_game_s_rule_gives(void)
{
	set_hiders();
	for (int from = 0; from < CITY_TOWERS; ++from)
		for (int patch = 0; patch < CITY_SEEN_PATCHES * CITY_SEEN_PATCHES; ++patch)
			for (int tower = 0; tower < CITY_TOWERS; ++tower)
				CHECK_EQ(seen(from, patch, tower), city_sees(from, patch, tower));
}

// The patch you're on, from where you are on the roof: its four quarters, and the edges belong
// to one of them
static void a_roof_s_four_patches(void)
{
	const city_tower *hub = city_tower_at(CITY_HUB_COLUMN, CITY_HUB_ROW);

	CHECK_EQ(0, city_seen_patch(hub, hub->out_min, hub->across_min));
	CHECK_EQ(1, city_seen_patch(hub, hub->out_max, hub->across_min));
	CHECK_EQ(2, city_seen_patch(hub, hub->out_min + 10, hub->across_max));
	CHECK_EQ(3, city_seen_patch(hub, hub->out_min + 250, hub->across_min + 250));
	CHECK_EQ(0, city_seen_patch(hub, hub->out_min + 249, hub->across_min + 249));
}

// It hides something: from the hub, deep among the towers, under half of them are left; and a
// roof always sees itself and the towers touching it
static void deep_in_the_city_most_towers_are_hidden(void)
{
	const int hub = CITY_HUB_ROW * CITY_COLUMNS + CITY_HUB_COLUMN;

	for (int patch = 0; patch < CITY_SEEN_PATCHES * CITY_SEEN_PATCHES; ++patch)
	{
		int count = 0;

		for (int tower = 0; tower < CITY_TOWERS; ++tower)
			count += city_sees(hub, patch, tower) ? 1 : 0;
		CHECK(count < CITY_TOWERS / 2 + 4);
		CHECK(city_sees(hub, patch, hub));
		CHECK(city_sees(hub, patch, hub - 1));			  // the tower west of it, touching
		CHECK(city_sees(hub, patch, hub + CITY_COLUMNS)); // and south
	}
}

/*
 * Through the corridor's doorway (city_seen_doorway): the row is what the game's rule gives from
 * the doorway's two ends, bit for bit; every tower it leaves out is hidden from each of a row of
 * points along the doorway too (not only its ends: the convexity it rests on); the entry's roof is
 * seen; and it leaves out a fair share
 */
static bool doorway_hidden_from(int across, int tower)
{
	const skyline_box target = box_of(&city_towers[tower]);

	for (int h = 0; h < HIDERS; ++h)
		if (h != tower && hiders[h].top >= target.top && hiders[h].top >= CITY_DOORWAY_EYE &&
			hides_from(CORRIDOR_LENGTH, across, CITY_DOORWAY_EYE, &hiders[h], &target))
			return true;
	return false;
}

static void through_the_doorway_only_what_can_be_seen(void)
{
	const int entry = 5 * CITY_COLUMNS; // row 5, column 0: the entry's roof
	int count = 0;

	set_hiders();
	for (int t = 0; t < CITY_TOWERS; ++t)
	{
		const bool is_seen = ((city_seen_doorway[t >> 3] >> (t & 7)) & 1) != 0;
		const skyline_box target = box_of(&city_towers[t]);
		bool hidden = false;

		// The rule: one hider hides it from both ends
		for (int h = 0; h < HIDERS && !hidden; ++h)
			hidden = h != t && hiders[h].top >= target.top && hiders[h].top >= CITY_DOORWAY_EYE &&
					 hides_from(CORRIDOR_LENGTH, 0, CITY_DOORWAY_EYE, &hiders[h], &target) &&
					 hides_from(CORRIDOR_LENGTH, CITY_DOORWAY_WIDE, CITY_DOORWAY_EYE, &hiders[h], &target);
		CHECK_EQ(!hidden, is_seen);
		count += is_seen ? 1 : 0;
		if (!is_seen)
			for (int across = 0; across <= CITY_DOORWAY_WIDE; across += CITY_DOORWAY_WIDE / 10)
				CHECK(doorway_hidden_from(across, t));
	}
	CHECK(((city_seen_doorway[entry >> 3] >> (entry & 7)) & 1) != 0);
	CHECK(count < CITY_TOWERS * 3 / 4);
}

void run_city_seen_tests(void)
{
	RUN(through_the_doorway_only_what_can_be_seen);
	RUN(the_table_is_what_the_game_s_rule_gives);
	RUN(a_roof_s_four_patches);
	RUN(deep_in_the_city_most_towers_are_hidden);
}
